* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.card {
  width: 300px;
  padding: 20px;
  /* Width stays exactly 300px! */
}

.container {
  display: flex;
  justify-content: space-between; /* Spacing along row */
  align-items: center; /* Vertical centering */
  gap: 16px; /* Modern spacing between children */
}

.dashboard {
  display: grid;
  grid-template-columns: 250px 1fr;
  grid-template-rows: 60px 1fr;
  height: 100vh;
}

:root {
  --primary: #2563eb;
  --surface: #ffffff;
  --text: #1f2937;
}

.button {
  background-color: var(--primary);
  color: var(--surface);
}

/* Mobile first base style */
.grid {
  display: grid;
  grid-template-columns: 1fr;
}

/* Desktop override */
@media (min-width: 768px) {
  .grid {
    grid-template-columns: 1fr 1fr;
  }
}

.button {
  background: blue;
  transition: background 0.2s ease;
}

.button:hover {
  background: darkblue;
}

.button:focus-visible {
  outline: 2px solid cyan;
  outline-offset: 2px;
}

@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.05); }
  100% { transform: scale(1); }
}

.alert {
  animation: pulse 2s infinite ease-in-out;
}

.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 50; /* Creates a high stacking context */
}

