const users = [
  { name: 'Alice', active: true },
  { name: 'Bob', active: false },
  { name: 'Charlie', active: true }
];

// Get names of active users
const activeNames = users
  .filter(user => user.active)
  .map(user => user.name);

console.log(activeNames); // ['Alice', 'Charlie']

